/* ---- البدل: focused, deterministic coverage of the four kinds. -----------------------------
   Al-Tuḥfah pp. 135–138. Every kind is built through frozen template authority, proven to inherit
   its mubdal minhu's state, to take its own canonical sign, and to carry — or refuse — the ضمير
   عائد exactly as its kind requires. The negative half is what keeps البدل from collapsing into
   the other three followers. */
function runBadalFocusedTests(){
  const templateFor=(inflection,state)=>api.templates.find(item=>item.followerKind===api.BADAL_KIND
    &&item.state===state&&item.form===inflection);
  const analyzed=(template,built)=>api.completeNominalAnalysis({...built,templateId:template.stableId,
    templateStarts:template.starts,templateForm:template.form,templateState:template.state,templateSign:template.sign});
  let builds=0,trips=0,negatives=0;
  const built=new Map(),kindsSeen=new Set(),statesSeen=new Set();
  for(const pairKey of Object.keys(api.BADAL_PAIR_REGISTRY)){
    const pair=api.BADAL_PAIR_REGISTRY[pairKey];
    assert(Object.isFrozen(pair)&&Object.isFrozen(pair.followed)&&Object.isFrozen(pair.follower),
      pairKey+' is not immutable lexical authority');
    for(const host of pair.hosts){
      const template=templateFor(pair.followerInflection==='fiveNouns'?'fiveNouns':'singular',host);
      assert(template&&template.followerPairKeys.includes(pairKey),
        pairKey+'/'+host+' is not reachable through frozen template authority');
      const data=analyzed(template,api.buildBadalExercise(pairKey,host));
      const followerIndex=data.tokens.findIndex(token=>token.grammar.role==='badal');
      const follower=data.tokens[followerIndex],followed=data.tokens[followerIndex-1];
      const authority=api.deriveBadalFollowerAuthority(data,followerIndex);
      assert(authority.authorized&&authority.kind===api.BADAL_KIND&&authority.pairKey===pairKey
        &&authority.subtype===pair.subtype&&authority.followedId===followed.id
        &&authority.followerId===follower.id,pairKey+'/'+host+' lost its mubdal-minhu/subtype authority');
      kindsSeen.add(pair.subtype);statesSeen.add(host);
      // The state is INHERITED from the mubdal minhu; the sign is the follower's own morphology.
      assert(follower.state===followed.state&&follower.state===host,
        pairKey+'/'+host+' did not inherit the mubdal minhu state');
      assert(api.safeSignId(follower.sign)===api.GRAMMAR_RULES.nounInflection[follower.inflection][host][0],
        pairKey+'/'+host+' does not carry its own canonical sign');
      assert(follower.ruleId==='R_BADAL',pairKey+'/'+host+' is not bound to R_BADAL');
      // The ضمير عائد: required for baʿḍ and ishtimāl, forbidden for muṭābiq and ghalaṭ.
      const needsPronoun=api.BADAL_PRONOUN_REQUIRED.includes(pair.subtype);
      assert(Boolean(pair.pronounId)===needsPronoun,pairKey+' declares a pronoun its kind does not match');
      if(needsPronoun){
        const pronoun=api.TAWKID_ATTACHED_PRONOUNS[pair.pronounId];
        assert(pronoun&&pronoun.gender===pair.antecedentGender&&pronoun.number===pair.antecedentNumber,
          pairKey+' pronoun does not agree with its registered antecedent');
        assert(follower.word.endsWith(pronoun.surfaceByState[host]),
          pairKey+'/'+host+' lost the ضمير عائد the source requires');
      }
      // Learner-facing analysis names the kind and uses مخفوض, never مجرور.
      assert(follower.ar.includes(api.BADAL_KIND_LABELS[pair.subtype].ar),
        pairKey+'/'+host+' does not name its kind in the rendered iʿrāb');
      assert(!/مَجْرُور/.test(follower.ar),pairKey+'/'+host+' used مجرور instead of مخفوض');
      assert(follower.why.ids.includes('WHY_STATE_BADAL_INHERITED')
        &&follower.why.ids.some(id=>id.startsWith('WHY_ROLE_BADAL_'))
        &&follower.why.ids.some(id=>id.startsWith('WHY_BADAL_')),
        pairKey+'/'+host+' is missing its role, state or condition Why');
      assert(api.validateExercise(clone(data)).length===0,pairKey+'/'+host+' does not validate');
      assert(api.composeCanonicalTranslation(data)===data.translation,
        pairKey+'/'+host+' builder and composer disagree');
      builds++;
      const snapshot=api.createExerciseSnapshot(data);
      assert(snapshot&&snapshot.schemaVersion===3,pairKey+'/'+host+' did not snapshot at v3');
      const restored=api.restoreExerciseSnapshot(clone(snapshot));
      assert(restored&&restored.sentence===data.sentence&&restored.translation===data.translation
        &&restored.tokens.map(t=>t.ar).join('|')===data.tokens.map(t=>t.ar).join('|'),
        pairKey+'/'+host+' did not survive a History round trip');
      assert(api.validateExercise(clone(restored)).length===0,pairKey+'/'+host+' restored invalid');
      trips++;
      built.set(pairKey+'/'+host,data);
    }
  }
  assert(kindsSeen.size===4&&['mutabiq','baad','ishtimal','ghalat'].every(k=>kindsSeen.has(k)),
    'not all four kinds of badal are productive: '+[...kindsSeen].join(','));
  assert(statesSeen.size===3&&['raf','nasb','jarr'].every(s=>statesSeen.has(s)),
    'badal does not cover rafʿ, naṣb and khafḍ: '+[...statesSeen].join(','));
  const mustReject=(label,source,mutate,code)=>{
    const data=clone(source);mutate(data);
    const failures=api.validateExercise(data);
    assert(failures.length>0,'badal boundary "'+label+'" produced a CLEAN exercise');
    if(code)assert(failures.some(f=>f.code===code),
      'badal boundary "'+label+'" failed as '+failures.map(f=>f.code).join(',')+' (wanted '+code+')');
    negatives++;
  };
  const mutabiq=built.get('mutabiqFather/nasb'),baad=built.get('baadQuranThird/nasb'),
        ishtimal=built.get('ishtimalTeacherKnowledge/nasb'),ghalat=built.get('ghalatBookNotebook/nasb');
  const followerIndexOf=data=>data.tokens.findIndex(t=>t.grammar.role==='badal');
  mustReject('wrong inherited state',baad,data=>{data.tokens[followerIndexOf(data)].state='raf'},'E_BADAL_AUTHORITY');
  mustReject('wrong mubdal minhu',baad,data=>{
    const followed=data.tokens[followerIndexOf(data)-1];
    followed.word=api.BADAL_PAIR_REGISTRY.baadBreadHalf.followed.acc;
    followed.expectedSurface=followed.word;followed.surfaceHint=followed.word;
  },'E_BADAL_AUTHORITY');
  mustReject('a part-whole pair relabelled as ishtimāl',baad,data=>{
    data.relationships.find(item=>item.kind===api.BADAL_KIND).subtype='ishtimal';
  },'E_FOLLOWER_RELATION');
  mustReject('an ishtimāl pair relabelled as part-whole',ishtimal,data=>{
    data.relationships.find(item=>item.kind===api.BADAL_KIND).subtype='baad';
  },'E_FOLLOWER_RELATION');
  mustReject('the ضمير عائد stripped',baad,data=>{
    const follower=data.tokens[followerIndexOf(data)];
    follower.word=api.BADAL_PAIR_REGISTRY.ghalatBookNotebook.follower.acc;
    follower.expectedSurface=follower.word;follower.surfaceHint=follower.word;
  },'E_BADAL_AUTHORITY');
  mustReject('an arbitrary adjacent noun promoted to badal',ghalat,data=>{
    const follower=data.tokens[followerIndexOf(data)];
    follower.word=api.BADAL_PAIR_REGISTRY.baadQuranThird.followed.acc;
    follower.expectedSurface=follower.word;follower.surfaceHint=follower.word;
  },'E_BADAL_AUTHORITY');
  mustReject('forged follower target',mutabiq,data=>{
    data.relationships.find(item=>item.kind===api.BADAL_KIND).followedId=data.tokens[0].id;
  },'E_FOLLOWER_RELATION');
  // Category separation, both directions.
  const badalIndex=followerIndexOf(mutabiq);
  assert(api.deriveNaatFollowerAuthority(mutabiq,badalIndex).authorized===false
    &&api.deriveAtfFollowerAuthority(mutabiq,badalIndex).authorized===false
    &&api.deriveTawkidFollowerAuthority(mutabiq,badalIndex).authorized===false,
    'a badal crossed into naʿt, ʿaṭf or tawkīd authority');
  negatives++;
  const tawkidTemplate=api.templates.find(t=>t.followerKind===api.TAWKID_KIND&&t.state==='nasb');
  const tawkidSample=api.completeNominalAnalysis({...api.buildTawkidExercise('nafsSingularM','nasb'),
    templateId:tawkidTemplate.stableId,templateStarts:tawkidTemplate.starts,templateForm:tawkidTemplate.form,
    templateState:tawkidTemplate.state,templateSign:tawkidTemplate.sign});
  assert(api.deriveBadalFollowerAuthority(tawkidSample,
    tawkidSample.tokens.findIndex(t=>t.grammar.role==='tawkid')).authorized===false,
    'a tawkīd was admitted as a badal');
  negatives++;
  // History may not carry the subtype: a forged cache is discarded and rebuilt canonically.
  const forged=api.createExerciseSnapshot(ishtimal);
  forged.relationships.find(item=>item.kind===api.BADAL_KIND).subtype='ghalat';
  const rebuilt=api.restoreExerciseSnapshot(forged);
  assert(rebuilt&&rebuilt.relationships.some(item=>item.kind===api.BADAL_KIND&&item.subtype==='ishtimal'),
    'History did not discard and canonically rebuild a forged badal subtype');
  negatives++;
  console.log('Badal focused tests: '+builds+' canonical builds, '+trips+' History round trips, '
    +negatives+' negative/collision boundaries — green');
}
runBadalFocusedTests();
if(process.env.NAHW_FOCUSED_BADAL==='1')process.exit(0);
/* ---- نائب الفاعل: explicit passive capability, five rafʿ signs, both tenses. ---------------- */
function runNaibFailFocusedTests(){
  const templateFor=(inflection,tense)=>api.templates.find(item=>item.passiveTense===tense
    &&item.form===inflection&&item.state==='raf');
  const analyzed=(template,built)=>api.completeNominalAnalysis({...built,templateId:template.stableId,
    templateStarts:template.starts,templateForm:template.form,templateState:template.state,templateSign:template.sign});
  const clone=value=>JSON.parse(JSON.stringify(value));
  const built=new Map(),capabilitiesSeen=new Set();
  let builds=0,trips=0,negatives=0;
  for(const [pairKey,pair] of Object.entries(api.PASSIVE_DEPUTY_PAIRS)){
    assert(Object.isFrozen(pair)&&Object.isFrozen(pair.deputy),pairKey+' is not immutable deputy authority');
    for(const tense of ['past','present']){
      const template=templateFor(pair.inflection,tense);
      assert(template&&template.passivePairKeys.includes(pairKey),pairKey+'/'+tense+' is unreachable');
      const data=analyzed(template,api.buildPassiveExercise(pairKey,tense));
      const authority=api.derivePassiveConstructionAuthority(data);
      const verb=data.tokens[0],deputy=data.tokens[1],relation=data.relationships.find(item=>item.type==='passiveDeputy');
      assert(authority.authorized&&authority.pairKey===pairKey&&authority.tense===tense,
        pairKey+'/'+tense+' did not earn passive authority');
      assert(verb.grammar.voice===api.PASSIVE_VOICE&&verb.grammar.morphology.subjectMode==='deputy'
        &&verb.voiceRuleId===(tense==='past'?'R_PASSIVE_PAST_FORM':'R_PASSIVE_PRESENT_FORM'),
        pairKey+'/'+tense+' lost passive morphology or source ownership');
      assert(deputy.grammar.role==='naibFail'&&deputy.state==='raf'&&deputy.ruleId==='R_NAIB_FAIL_RAF',
        pairKey+'/'+tense+' did not produce a raised deputy subject');
      assert(api.safeSignId(deputy.sign)===api.GRAMMAR_RULES.nounInflection[pair.inflection].raf[0],
        pairKey+'/'+tense+' bypassed the canonical noun rafʿ matrix');
      assert(relation&&relation.ruleId==='RL_PASSIVE_DEPUTY'&&relation.verbId===verb.id
        &&relation.deputyId===deputy.id&&relation.pairKey===pairKey,
        pairKey+'/'+tense+' lacks its canonical reciprocal relationship');
      assert(!data.tokens.some(item=>['faail','object'].includes(item.grammar.role))
        &&!data.relationships.some(item=>item.type==='verbSubject'||item.type==='verbObject'),
        pairKey+'/'+tense+' retained an active subject or object');
      assert(verb.ar.includes('مَبْنِيٌّ لِلْمَجْهُولِ')&&deputy.ar.includes('نَائِبُ فَاعِلٍ')
        &&verb.why.ids.includes(tense==='past'?'WHY_PASSIVE_PAST_FORM':'WHY_PASSIVE_PRESENT_FORM')
        &&deputy.why.ids.includes('WHY_ROLE_NAIB_FAIL')
        &&verb.phraseWhy?.ids.includes('WHY_REL_PASSIVE_DEPUTY'),
        pairKey+'/'+tense+' learner-facing analysis or Why chain is incomplete');
      assert(api.canonicalPassiveTranslation(data)===data.translation&&api.composeCanonicalTranslation(data)===data.translation,
        pairKey+'/'+tense+' translation is not canonical');
      const snapshot=api.createExerciseSnapshot(data),restored=snapshot&&api.restoreExerciseSnapshot(snapshot);
      assert(restored&&api.validateExercise(clone(restored)).length===0
        &&api.derivePassiveConstructionAuthority(restored).authorized,
        pairKey+'/'+tense+' failed its History v3 round trip');
      assert(restored.sentence===data.sentence&&restored.translation===data.translation
        &&restored.tokens[0].gloss===verb.gloss&&restored.tokens[0].ar===verb.ar&&restored.tokens[1].ar===deputy.ar,
        pairKey+'/'+tense+' changed learner presentation after History');
      built.set(pairKey+'/'+tense,data);capabilitiesSeen.add(authority.capabilityKey);builds++;trips++;
    }
  }
  assert(capabilitiesSeen.size===Object.keys(api.PASSIVE_VERB_CAPABILITIES).length,
    'not every explicit passive capability is reachable');
  const base=built.get('katabaLesson/past');
  const mustReject=(label,mutate,expected='E_PASSIVE_AUTHORITY')=>{
    const data=clone(base);mutate(data);const failures=api.validateExercise(data);
    assert(failures.some(item=>item.code===expected),label+' was accepted: '+failures.map(item=>item.code).join(','));negatives++;
  };
  mustReject('deputy relabelled active',data=>{data.tokens[1].grammar.role='faail'});
  mustReject('passive voice removed',data=>{delete data.tokens[0].grammar.voice});
  mustReject('wrong deputy lexeme',data=>{data.tokens[1].word='الْبَابُ';data.tokens[1].surfaceHint='الْبَابُ';data.tokens[1].expectedSurface='الْبَابُ'});
  mustReject('active fāʿil reinserted',data=>{data.tokens.push(clone(data.tokens[1]));data.tokens[2].id='FORGED';data.tokens[2].target=false;data.tokens[2].grammar.role='faail'});
  mustReject('unregistered passive surface',data=>{data.tokens[0].word='ضُرِبَ';data.tokens[0].surfaceHint='ضُرِبَ';data.tokens[0].expectedSurface='ضُرِبَ'});
  mustReject('active surface given passive voice',data=>{data.tokens[0].word='كَتَبَ';data.tokens[0].surfaceHint='كَتَبَ';data.tokens[0].expectedSurface='كَتَبَ'});
  mustReject('deputy moved before verb',data=>{data.tokens.reverse()});
  mustReject('wrong passive source rule',data=>{data.tokens[0].voiceRuleId='R_PASSIVE_PRESENT_FORM'},'E_VOICE_RULE_OWNER');
  mustReject('invented voice label',data=>{data.tokens[0].grammar.voice='active'},'E_VOICE_OWNER');
  const forged=api.createExerciseSnapshot(base);
  forged.relationships[0].pairKey='fatahaDoor';forged.relationships[0].formerObjectAcc='الْبَابَ';
  const rebuilt=api.restoreExerciseSnapshot(forged);
  assert(rebuilt&&rebuilt.relationships[0].pairKey==='katabaLesson'
    &&rebuilt.relationships[0].formerObjectAcc===api.PASSIVE_DEPUTY_PAIRS.katabaLesson.deputy.acc,
    'History did not discard and canonically rebuild a forged passive relationship');
  negatives++;
  console.log('Naib al-Fail focused tests: '+builds+' canonical builds, '+trips+' History round trips, '
    +negatives+' negative/collision boundaries — green');
}
runNaibFailFocusedTests();
if(process.env.NAHW_FOCUSED_NAIB_FAIL==='1')process.exit(0);
/* ---- المفعول المطلق: three أنواع (pp. 146), two divisions (p. 147), five productive lanes. ---- */
function runMutlaqFocusedTests(){
  const clone=value=>JSON.parse(JSON.stringify(value));
  const analyzed=(template,built)=>api.completeNominalAnalysis({...built,templateId:template.stableId,
    templateStarts:template.starts,templateForm:template.form,templateState:template.state,templateSign:template.sign});
  const templateFor=pairKey=>api.templates.find(item=>item.mutlaqPairKeys.includes(pairKey));
  const built=new Map();
  const purposesSeen=new Set(),divisionsSeen=new Set(),lanesSeen=new Set();
  let builds=0,trips=0,negatives=0;
  assert(Object.isFrozen(api.MUTLAQ_PAIR_REGISTRY)&&Object.isFrozen(api.MUTLAQ_LEXEMES)
    &&Object.isFrozen(api.MUTLAQ_VERB_CAPABILITIES),'a mafʿūl-muṭlaq registry is mutable');
  for(const [pairKey,pair] of Object.entries(api.MUTLAQ_PAIR_REGISTRY)){
    assert(Object.isFrozen(pair),pairKey+' is not immutable pair authority');
    const template=templateFor(pairKey);
    assert(template,pairKey+' is unreachable: no template names it');
    const data=analyzed(template,api.buildMutlaqExercise(pairKey));
    const index=data.tokens.findIndex(item=>item.grammar.role==='mafulMutlaq');
    const masdar=data.tokens[index],verb=data.tokens[0];
    const authority=api.deriveMutlaqAuthority(data,index);
    const relation=data.relationships.find(item=>item.type==='absoluteObject');
    const masdarLexeme=api.MUTLAQ_LEXEMES[pair.masdarKey];
    assert(authority.authorized&&authority.pairKey===pairKey&&authority.purpose===pair.purpose
      &&authority.agreement===pair.agreement,pairKey+' did not earn absolute-object authority');
    assert(masdar.target&&masdar.state==='nasb'&&masdar.ruleId==='R_MAFUL_MUTLAQ_NASB'
      &&masdar.word===masdarLexeme.acc,pairKey+' did not produce its maṣdar as the manṣūb focus');
    assert(api.safeSignId(masdar.sign)===api.GRAMMAR_RULES.nounInflection[masdarLexeme.inflection].nasb[0],
      pairKey+' bypassed the canonical noun naṣb matrix');
    assert(verb.tense==='past'&&verb.word===pair.verbPast&&!verb.grammar.voice,
      pairKey+' lost its visible active past ʿāmil');
    assert(relation&&relation.ruleId==='RL_VERB_ABSOLUTE_OBJECT'&&relation.verbId===verb.id
      &&relation.masdarId===masdar.id&&relation.pairKey===pairKey,
      pairKey+' lacks its canonical reciprocal ʿāmil relationship');
    // The نوع lane is the only one that annexes, and it must actually annex.
    assert(Boolean(pair.qualifierKey)===Boolean(masdar.grammar.isMudaf)
      &&Boolean(pair.qualifierKey)===data.tokens.some(item=>item.grammar.role==='mudafIlayh'),
      pairKey+' disagrees with its registered iḍāfah declaration');
    assert(Boolean(pair.object)===data.tokens.some(item=>item.grammar.role==='object'),
      pairKey+' disagrees with its registered object declaration');
    assert(masdar.ar.includes('مَفْعُولٌ مُطْلَقٌ مَنْصُوبٌ')&&!/مجرور/.test(masdar.ar),
      pairKey+' learner-facing iʿrāb is not the canonical accusative wording');
    assert(masdar.why.ids.includes('WHY_ROLE_MAFUL_MUTLAQ_'+pair.purpose.toUpperCase())
      &&masdar.why.ids.includes('WHY_MUTLAQ_PURPOSE_'+pair.purpose.toUpperCase())
      &&masdar.why.ids.includes('WHY_MUTLAQ_DIVISION_'+pair.agreement.toUpperCase())
      &&masdar.why.ids.includes('WHY_STATE_MAFUL_MUTLAQ')
      &&masdar.phraseWhy?.ids.includes('WHY_REL_ABSOLUTE_OBJECT'),
      pairKey+' Why chain omits one of its two source claims');
    // Sacred order: the combined analysis sits on the maṣdar, beside the word being studied.
    assert(masdar.phraseAr&&masdar.phraseLabel==='Absolute object'
      &&data.tokens.every(item=>item===masdar||!item.phraseAr),
      pairKey+' put the combined analysis somewhere other than its maṣdar');
    assert(api.canonicalMutlaqTranslation(data)===data.translation
      &&api.composeCanonicalTranslation(data)===data.translation&&data.translation===pair.sentenceEn,
      pairKey+' translation is not canonical');
    assert(masdar.gloss===masdarLexeme.en,pairKey+' maṣdar gloss did not come from its registered lexeme');
    const snapshot=api.createExerciseSnapshot(data),restored=snapshot&&api.restoreExerciseSnapshot(snapshot);
    assert(restored&&api.validateExercise(clone(restored)).length===0
      &&api.deriveMutlaqAuthority(restored,index).authorized,
      pairKey+' failed its History v3 round trip');
    assert(restored.sentence===data.sentence&&restored.translation===data.translation
      &&restored.tokens[index].ar===masdar.ar&&restored.tokens[index].gloss===masdar.gloss,
      pairKey+' changed learner presentation after History');
    built.set(pairKey,data);purposesSeen.add(pair.purpose);divisionsSeen.add(pair.agreement);
    lanesSeen.add(template.stableId);builds++;trips++;
  }
  assert(purposesSeen.size===3&&divisionsSeen.size===2,
    'the three أنواع and both divisions of p. 147 are not all reachable');
  assert(lanesSeen.size===5,'not all five productive mafʿūl-muṭlaq lanes were exercised');
  // p. 147's letter test is a real test, not a label: both declarations are checked in both directions.
  assert(api.mutlaqSharesVerbLetters('قَعَدَ','قُعُودًا')&&api.mutlaqSharesVerbLetters('قَرَأَ','قِرَاءَتَيْنِ')
    &&!api.mutlaqSharesVerbLetters('جَلَسَ','قُعُودًا')&&!api.mutlaqSharesVerbLetters('قَامَ','وُقُوفًا'),
    'the لفظي/معنوي letter test no longer separates the two divisions');
  negatives++;
  const base=built.get('hifzDars');
  const mustReject=(label,mutate,expected='E_MUTLAQ_AUTHORITY')=>{
    const data=clone(base);mutate(data);const failures=api.validateExercise(data);
    assert(failures.some(item=>item.code===expected),label+' was accepted: '+failures.map(item=>item.code).join(','));negatives++;
  };
  mustReject('maṣdar relabelled a direct object',data=>{data.tokens[3].grammar.role='object'},'E_ORPHAN_OBJECT');
  mustReject('unregistered maṣdar surface',data=>{data.tokens[3].word='ضَرْبًا';data.tokens[3].surfaceHint='ضَرْبًا';data.tokens[3].expectedSurface='ضَرْبًا'});
  mustReject('maṣdar of another ʿāmil',data=>{const q=api.MUTLAQ_LEXEMES.quud;data.tokens[3].word=q.acc;data.tokens[3].surfaceHint=q.acc;data.tokens[3].expectedSurface=q.acc});
  mustReject('object swapped for one the pair does not name',data=>{data.tokens[2].word='الْقُرْآنَ';data.tokens[2].surfaceHint='الْقُرْآنَ';data.tokens[2].expectedSurface='الْقُرْآنَ'});
  mustReject('iḍāfah asserted without a muḍāf ilayh',data=>{data.tokens[3].grammar.isMudaf=true},'E_MUDAF_NO_COMPLEMENT');
  mustReject('maṣdar moved before its ʿāmil',data=>{data.tokens=[data.tokens[3],data.tokens[0],data.tokens[1],data.tokens[2]]});
  mustReject('wrong source rule on the maṣdar',data=>{data.tokens[3].ruleId='R_MAFUL_NASB'},'E_MUTLAQ_RULE');
  mustReject('maṣdar written marfūʿ',data=>{data.tokens[3].state='raf'},'E_ROLE_CASE');
  // A forged نوع or division must not survive: both are rebuilt from the registry, never restored.
  const forged=api.createExerciseSnapshot(base);
  const forgedRelation=forged.relationships.find(item=>item.type==='absoluteObject');
  assert(forgedRelation,'the snapshot carries no absolute-object relationship to forge');
  forgedRelation.purpose='adad';forgedRelation.agreement='manawi';forgedRelation.pairKey='quudLafzi';
  const rebuilt=api.restoreExerciseSnapshot(forged);
  const rebuiltRelation=rebuilt&&rebuilt.relationships.find(item=>item.type==='absoluteObject');
  assert(rebuiltRelation&&rebuiltRelation.purpose==='tawkid'&&rebuiltRelation.agreement==='lafzi'
    &&rebuiltRelation.pairKey==='hifzDars',
    'History did not discard and canonically rebuild a forged absolute-object relationship');
  negatives++;
  console.log('Maful Mutlaq focused tests: '+builds+' canonical builds, '+trips+' History round trips, '
    +negatives+' negative/collision boundaries — green');
}
runMutlaqFocusedTests();
if(process.env.NAHW_FOCUSED_MUTLAQ==='1')process.exit(0);
/* ---- المفعول فيه: both halves of Al-Tuḥfah pp. 148–152, plus the legacy lane's migration. ---- */
function runMafulFihFocusedTests(){
  const clone=value=>JSON.parse(JSON.stringify(value));
  const analyzed=(template,built)=>api.completeNominalAnalysis({...built,templateId:template.stableId,
    templateStarts:template.starts,templateForm:template.form,templateState:template.state,templateSign:template.sign});
  const templateFor=pairKey=>api.templates.find(item=>item.mafulFihPairKeys.includes(pairKey));
  const built=new Map();
  const kindsSeen=new Set(),lanesSeen=new Set();
  let builds=0,trips=0,negatives=0;
  assert(Object.isFrozen(api.MAFUL_FIH_LEXEMES)&&Object.isFrozen(api.MAFUL_FIH_PAIR_REGISTRY)
    &&Object.isFrozen(api.MAFUL_FIH_WEEKDAYS),'a mafʿūl-fīh registry is mutable');
  /* Byte safety, asserted rather than trusted: every registered ẓarf must be findable under its own
     stored literal, and its accusative surface must index straight back to it. A hand-typed
     combining-mark difference fails here instead of silently reaching surfaceHint. */
  for(const [key,lexeme] of Object.entries(api.MAFUL_FIH_LEXEMES)){
    assert(Object.isFrozen(lexeme),key+' is not immutable ẓarf authority');
    assert(api.MAFUL_FIH_BY_SURFACE[lexeme.acc]===lexeme,key+': its accusative surface does not index back to it');
    assert(lexeme.senseAr&&lexeme.senseEn,key+': carries no source sense');
    if(lexeme.indexed){
      const registered=api.nounFormIndex.get(lexeme.acc);
      assert(registered&&registered.lexeme===lexeme,key+': did not round-trip through the noun index');
    }else{
      assert(!api.nounFormIndex.has(lexeme.acc),key+': is declared unindexed but the noun index owns it');
    }
    // p. 151: a place ẓarf may only ever be مبهم.
    if(lexeme.kind===api.MAFUL_FIH_KINDS.place){
      assert(lexeme.zarfClass===api.MAFUL_FIH_CLASSES.mubham,key+': a non-mubham place reached the registry');
    }
    negatives++;
  }
  for(const [pairKey,pair] of Object.entries(api.MAFUL_FIH_PAIR_REGISTRY)){
    const template=templateFor(pairKey);
    assert(template,pairKey+' is unreachable: no template names it');
    const data=analyzed(template,api.buildMafulFihExercise(pairKey));
    const index=data.tokens.findIndex(item=>item.grammar.role===api.MAFUL_FIH_ROLE);
    const zarf=data.tokens[index],amil=data.tokens[0];
    const authority=api.deriveMafulFihAuthority(data,index);
    const relation=data.relationships.find(item=>item.type==='zarf');
    const lexeme=api.MAFUL_FIH_LEXEMES[pair.lexemeKey];
    assert(authority.authorized&&authority.pairKey===pairKey&&authority.kind===lexeme.kind
      &&authority.amilKind==='verb',pairKey+' did not earn mafʿūl-fīh authority');
    assert(zarf.target&&zarf.state==='nasb'&&zarf.ruleId==='R_ZARF_NASB'&&zarf.word===lexeme.acc,
      pairKey+' did not produce its ẓarf as the manṣūb focus');
    assert(api.safeSignId(zarf.sign)===api.GRAMMAR_RULES.nounInflection[lexeme.inflection].nasb[0],
      pairKey+' bypassed the canonical noun naṣb matrix');
    assert(relation&&relation.ruleId==='RL_VERB_ZARF'&&relation.verbId===amil.id
      &&relation.zarfId===zarf.id&&relation.kind===lexeme.kind,
      pairKey+' lacks its canonical reciprocal ʿāmil relationship');
    assert(Boolean(lexeme.mudaf)===Boolean(zarf.grammar.isMudaf)
      &&Boolean(lexeme.mudaf)===data.tokens.some(item=>item.grammar.role==='mudafIlayh'),
      pairKey+' disagrees with its registered iḍāfah declaration');
    // §6 — the whole-word iʿrāb names the chapter and its half, never a bare English-style label.
    assert(zarf.ar.includes('مَفْعُولٌ فِيهِ '+api.MAFUL_FIH_KIND_LABELS[lexeme.kind].ar+' مَنْصُوبٌ')
      &&!zarf.ar.includes('ظَرْفٌ مَنْصُوبٌ')&&!/مجرور/.test(zarf.ar),
      pairKey+' learner-facing iʿrāb is not the canonical mafʿūl-fīh wording');
    assert(zarf.why.ids.includes('WHY_ROLE_MAFUL_FIH_'+lexeme.kind.toUpperCase())
      &&zarf.why.ids.includes('WHY_STATE_MAFUL_FIH')
      &&zarf.phraseWhy?.ids.includes('WHY_REL_VERB_ZARF'),
      pairKey+' Why chain is incomplete');
    // The one source line differs in kind between the halves, and each must be the right one.
    if(lexeme.kind===api.MAFUL_FIH_KINDS.place){
      assert(zarf.why.ids.includes('WHY_MAFUL_FIH_PLACE_MUBHAM'),pairKey+' omits p. 151’s place restriction');
    }else{
      assert(zarf.why.ids.includes(lexeme.zarfClass
        ?'WHY_MAFUL_FIH_TIME_'+lexeme.zarfClass.toUpperCase():'WHY_MAFUL_FIH_TIME_SENSE'),
        pairKey+' states a class the source does not give it');
    }
    assert(zarf.phraseAr&&zarf.phraseLabel==='Ẓarf construction',pairKey+' has no combined ẓarf analysis');
    assert(api.canonicalMafulFihTranslation(data)===data.translation
      &&api.composeCanonicalTranslation(data)===data.translation&&data.translation===pair.sentenceEn,
      pairKey+' translation is not canonical');
    assert(zarf.gloss===lexeme.en,pairKey+' ẓarf gloss did not come from its registered lexeme');
    const snapshot=api.createExerciseSnapshot(data),restored=snapshot&&api.restoreExerciseSnapshot(snapshot);
    assert(restored&&api.validateExercise(clone(restored)).length===0
      &&api.deriveMafulFihAuthority(restored,index).authorized,
      pairKey+' failed its History v3 round trip');
    assert(restored.sentence===data.sentence&&restored.translation===data.translation
      &&restored.tokens[index].ar===zarf.ar&&restored.tokens[index].gloss===zarf.gloss,
      pairKey+' changed learner presentation after History');
    built.set(pairKey,data);kindsSeen.add(lexeme.kind);lanesSeen.add(template.stableId);builds++;trips++;
  }
  assert(kindsSeen.size===2,'both halves of the chapter are not reachable: '+[...kindsSeen].join(','));
  assert(lanesSeen.size===3,'not all three productive mafʿūl-fīh lanes were exercised');
  /* §14 — the migration. The inherited «مَعَ» lane must now run through the SAME authority, and its
     learner-facing grammar must have stopped being the vague pre-migration label. */
  {
    let seen=0;
    for(const template of api.templates.filter(item=>!item.mafulFihPairKeys.length)){
      for(let attempt=0;attempt<60&&!seen;attempt++){
        const data=api.buildTemplate(template.id);
        const index=data.tokens.findIndex(item=>item.grammar.role===api.MAFUL_FIH_ROLE);
        if(index<0)continue;
        const zarf=data.tokens[index],authority=api.deriveMafulFihAuthority(data,index);
        assert(authority.authorized&&!authority.pairKey&&authority.kind===api.MAFUL_FIH_KINDS.place,
          template.stableId+': the inherited ẓarf lane did not migrate onto the canonical authority');
        assert(zarf.ar.includes('مَفْعُولٌ فِيهِ ظَرْفُ مَكَانٍ مَنْصُوبٌ')&&!zarf.ar.includes('ظَرْفٌ مَنْصُوبٌ'),
          template.stableId+': the inherited ẓarf kept its pre-migration label');
        assert(zarf.why.ids.includes('WHY_STATE_MAFUL_FIH')&&!zarf.why.ids.includes('WHY_ROLE_ZARF_GENERIC'),
          template.stableId+': the inherited ẓarf kept a pre-migration Why rule');
        const restored=api.restoreExerciseSnapshot(api.createExerciseSnapshot(data));
        assert(restored&&api.validateExercise(clone(restored)).length===0,
          template.stableId+': the inherited ẓarf lane lost its History round trip');
        seen++;trips++;
      }
      if(seen)break;
    }
    assert(seen===1,'the inherited «مَعَ» ẓarf lane was never produced');
  }
  const base=built.get('amamaTeacher');
  const timeBase=built.get('saharStudy');
  const mustReject=(label,source,mutate,expected='E_MAFUL_FIH_AUTHORITY')=>{
    const data=clone(source);mutate(data);const failures=api.validateExercise(data);
    assert(failures.some(item=>item.code===expected),label+' was accepted: '+failures.map(item=>item.code).join(','));negatives++;
  };
  /* §11 — the collisions. A noun does not become a ẓarf by being manṣūb, and the source's own
     mukhtaṣṣ places must stay جار ومجرور territory rather than becoming accusative ẓarfs. */
  const mosque=api.mafulFihNoun('places','the mosque');
  mustReject('a mukhtaṣṣ place promoted to ẓarf',base,data=>{
    data.tokens[2].word=mosque.acc;data.tokens[2].surfaceHint=mosque.acc;data.tokens[2].expectedSurface=mosque.acc;
    data.tokens[2].grammar.isMudaf=false;data.tokens.splice(3,1);
  });
  mustReject('a direct object relabelled a ẓarf',timeBase,data=>{data.tokens[2].grammar.role=api.MAFUL_FIH_ROLE});
  mustReject('an unregistered time noun inventing the role',timeBase,data=>{
    data.tokens[3].word='شَهْرًا';data.tokens[3].surfaceHint='شَهْرًا';data.tokens[3].expectedSurface='شَهْرًا';
  });
  mustReject('a ẓarf with no ʿāmil at all',timeBase,data=>{data.tokens.splice(0,1)});
  mustReject('a muḍāf ẓarf stripped of its complement',base,data=>{data.tokens.splice(3,1)});
  mustReject('a ẓarf outside the template’s registered pairs',base,data=>{
    const other=api.MAFUL_FIH_LEXEMES.tahta;
    data.tokens[2].word=other.acc;data.tokens[2].surfaceHint=other.acc;data.tokens[2].expectedSurface=other.acc;
  });
  mustReject('a ẓarf written marfūʿ',timeBase,data=>{data.tokens[3].state='raf'},'E_ROLE_CASE');
  mustReject('a ẓarf bound to the wrong source rule',timeBase,data=>{data.tokens[3].ruleId='R_MAFUL_NASB'},'E_MAFUL_FIH_RULE');
  mustReject('a forged ẓarf kind on the relationship',timeBase,data=>{
    data.relationships.find(item=>item.type==='zarf').kind=api.MAFUL_FIH_KINDS.place;
  },'E_MAFUL_FIH_RELATION');
  /* A forged kind or lexeme must not survive History either: both are rebuilt from the registry. */
  const forged=api.createExerciseSnapshot(timeBase);
  const forgedRelation=forged.relationships.find(item=>item.type==='zarf');
  assert(forgedRelation,'the snapshot carries no ẓarf relationship to forge');
  forgedRelation.kind=api.MAFUL_FIH_KINDS.place;forgedRelation.lexemeKey='amama';
  const rebuilt=api.restoreExerciseSnapshot(forged);
  const rebuiltRelation=rebuilt&&rebuilt.relationships.find(item=>item.type==='zarf');
  assert(rebuiltRelation&&rebuiltRelation.kind===api.MAFUL_FIH_KINDS.time&&rebuiltRelation.lexemeKey==='saharan',
    'History did not discard and canonically rebuild a forged ẓarf relationship');
  negatives++;
  console.log('Maful Fih focused tests: '+builds+' canonical builds, '+trips+' History round trips, '
    +negatives+' negative/registry boundaries — green');
}
runMafulFihFocusedTests();
if(process.env.NAHW_FOCUSED_MAFUL_FIH==='1')process.exit(0);
/* ---- «لا» النافية للجنس: Al-Tuḥfah pp. 166–168. Only the muʿrab type is productive, so these
   tests prove the four conditions structurally AND that this لا cannot be confused with the
   ordinary negating لا the app already produces on the same surface. ---- */
function runLaJinsFocusedTests(){
  const clone=value=>JSON.parse(JSON.stringify(value));
  const analyzed=(template,built)=>api.completeNominalAnalysis({...built,templateId:template.stableId,
    templateStarts:template.starts,templateForm:template.form,templateState:template.state,templateSign:template.sign});
  const template=api.templates.find(item=>item.laJinsPairKeys.length);
  assert(template,'no template names the «لا» al-jins pairs');
  const built=new Map();
  let builds=0,trips=0,negatives=0;
  assert(Object.isFrozen(api.LA_JINS_PAIR_REGISTRY)&&Object.isFrozen(api.LA_JINS_LEXEMES)
    &&Object.isFrozen(api.LA_JINS_COMPLEMENTS)&&Object.isFrozen(api.LA_JINS_KHABARS),
    'a «لا» al-jins registry is mutable');
  /* Byte gate, plus the matn's own «تَنْصِبُ النَّكِرَاتِ بِغَيْرِ تَنْوِينٍ»: the noun is stored in its
     muḍāf accusative, carrying no tanwīn at all. */
  for(const [key,lexeme] of Object.entries(api.LA_JINS_LEXEMES)){
    assert(api.nounFormIndex.get(lexeme.acc)?.lexeme===lexeme,
      key+' does not round-trip byte-for-byte through the noun index');
    assert(!lexeme.acc.startsWith('ال')&&!/(?:ً|ٌ|ٍ)$/u.test(lexeme.acc),
      key+' is definite or carries tanwīn, which the matn excludes');
    negatives++;
  }
  for(const [key,lexeme] of Object.entries(api.LA_JINS_KHABARS)){
    assert(api.nounFormIndex.get(lexeme.nom)?.lexeme===lexeme&&!lexeme.nom.startsWith('ال'),
      key+' is not a registered indefinite khabar');
    negatives++;
  }
  for(const [pairKey,pair] of Object.entries(api.LA_JINS_PAIR_REGISTRY)){
    assert(Object.isFrozen(pair),pairKey+' is not immutable «لا» al-jins pair authority');
    assert(template.laJinsPairKeys.includes(pairKey),pairKey+' is unreachable');
    const data=analyzed(template,api.buildLaJinsExercise(pairKey));
    const index=data.tokens.findIndex(item=>item.grammar.role===api.ISM_LA_ROLE);
    const particle=data.tokens[0],ism=data.tokens[index];
    const complement=data.tokens[2],khabar=data.tokens[3];
    const authority=api.deriveLaJinsAuthority(data,index);
    const relation=data.relationships.find(item=>item.type==='laJins');
    assert(authority.authorized&&authority.pairKey===pairKey,pairKey+' did not earn exact «لا» al-jins authority');
    /* This لا carries its OWN identity. That is what keeps a generic negating لا — same surface,
       different particle — from ever authorizing the frame. */
    assert(particle.grammar.type==='particle'&&particle.grammar.particleType===api.LA_JINS_PARTICLE_TYPE
      &&particle.grammar.particleType!=='laNafiyaContext'&&particle.ruleId===api.LA_JINS_PARTICLE.ruleId
      &&particle.gloss===api.LA_JINS_PARTICLE.gloss,pairKey+' lost the class-negating لا identity');
    assert(ism.target&&ism.state==='nasb'&&ism.ruleId==='R_ISM_LA_NASB'&&ism.grammar.isMudaf
      &&api.safeSignId(ism.sign)===api.GRAMMAR_RULES.nounInflection.singular.nasb[0],
      pairKey+' did not produce its اسم لا as the manṣūb muḍāf focus');
    assert(khabar.state==='raf'&&khabar.ruleId==='R_KHABAR_LA_RAF',pairKey+' lost its marfūʿ khabar');
    // Conditions 1 and 3 — both participants indefinite; condition 2 — adjacency; condition 4 — no repeat.
    assert(!ism.word.startsWith('ال')&&!khabar.word.startsWith('ال')&&!complement.word.startsWith('ال'),
      pairKey+' produced a definite participant');
    assert(data.tokens.indexOf(particle)===0&&index===1,pairKey+' separated «لا» from its noun');
    assert(data.tokens.filter(item=>item.grammar.particleType===api.LA_JINS_PARTICLE_TYPE).length===1,
      pairKey+' repeated «لا»');
    // The muḍāf ilayh keeps this project's khafḍ terminology, never مجرور.
    assert(complement.grammar.role==='mudafIlayh'&&complement.state==='jarr'
      &&complement.ar.includes('مَخْفُوضٌ')&&!complement.ar.includes('مَجْرُورٌ'),
      pairKey+' lost the khafḍ terminology on its muḍāf ilayh');
    assert(relation&&relation.ruleId==='RL_LA_JINS_NOUN_KHABAR'&&relation.particleId===particle.id
      &&relation.ismId===ism.id&&relation.khabarId===khabar.id,pairKey+' lacks its canonical frame relationship');
    assert(api.isSourceAuthorized(ism.ruleId)&&api.isSourceAuthorized(khabar.ruleId)
      &&api.isSourceAuthorized(relation.ruleId)&&api.isSourceAuthorized('R_LA_JINS_CONDITIONS')
      &&api.isSourceAuthorized('R_LA_NAFIYA_JINS'),pairKey+' lost source ownership');
    assert(ism.ar.includes('اسْمُ «لَا» النَّافِيَةِ لِلْجِنْسِ مَنْصُوبٌ')&&!ism.ar.includes('مَبْنِيٌّ')
      &&khabar.ar.includes('خَبَرُ «لَا» النَّافِيَةِ لِلْجِنْسِ مَرْفُوعٌ')
      &&ism.why.ids.includes('WHY_ROLE_ISM_LA')&&ism.why.ids.includes('WHY_STATE_ISM_LA')
      &&ism.why.ids.includes('WHY_LA_JINS_CONDITIONS')
      &&khabar.why.ids.includes('WHY_ROLE_KHABAR_LA')
      &&particle.why.ids.includes('WHY_PARTICLE_LA_NAFIYA_JINS')
      &&khabar.phraseWhy?.ids.includes('WHY_REL_LA_JINS'),pairKey+' Why/iʿrāb chain is incomplete');
    assert(api.canonicalLaJinsTranslation(data)===pair.sentenceEn
      &&api.composeCanonicalTranslation(data)===pair.sentenceEn&&data.translation===pair.sentenceEn,
      pairKey+' translation is not canonical natural English');
    const snapshot=api.createExerciseSnapshot(data),restored=snapshot&&api.restoreExerciseSnapshot(snapshot);
    assert(restored&&api.validateExercise(clone(restored)).length===0
      &&api.deriveLaJinsAuthority(restored,index).authorized,pairKey+' failed its History v3 round trip');
    assert(restored.sentence===data.sentence&&restored.translation===data.translation
      &&restored.tokens[index].ar===ism.ar&&restored.tokens[0].gloss===particle.gloss,
      pairKey+' changed learner presentation after History');
    built.set(pairKey,data);builds++;trips++;
  }
  const base=built.get('seekerOfKnowledge');
  const mustReject=(label,source,mutate,expected='E_LA_JINS_AUTHORITY')=>{
    const data=clone(source);mutate(data);const failures=api.validateExercise(data);
    assert(failures.some(item=>item.code===expected),label+' was accepted: '+failures.map(item=>item.code).join(','));negatives++;
  };
  /* لا النافية للجنس vs every other لا this app produces. The surface is identical, so only the
     particle identity can separate them — which is exactly what these two prove. */
  mustReject('the non-governing negating لا claiming this frame',base,data=>{
    data.tokens[0].grammar.particleType='laNafiyaContext';data.tokens[0].ruleId='R_LA_NAFIYA_CONTEXT';
  });
  mustReject('an ʿaṭf لا claiming this frame',base,data=>{
    const atfLa=Object.values(api.ATF_CONJUNCTION_REGISTRY).find(item=>item.surface==='لَا');
    data.tokens[0].grammar.particleType=atfLa?atfLa.particleType:'atfBalNegation';
  });
  // The four conditions, each broken in turn.
  mustReject('definite اسم لا',base,data=>{
    const definite=api.nounLexicons.singularPeople.find(item=>item.en==='the student');
    const t=data.tokens[1];t.word=definite.acc;t.surfaceHint=definite.acc;t.expectedSurface=definite.acc;
  },'E_LA_JINS_DEFINITE');
  mustReject('definite خبر لا',base,data=>{
    const definite=api.nounLexicons.singularThings.find(item=>item.en==='the book');
    const t=data.tokens[3];t.word=definite.nom;t.surfaceHint=definite.nom;t.expectedSurface=definite.nom;
  },'E_LA_JINS_DEFINITE');
  mustReject('separator between لا and its noun',base,data=>{
    data.tokens.splice(1,0,{word:'الْيَوْمَ',surfaceHint:'الْيَوْمَ',gloss:'today',id:data.templateId+':T0',
      grammar:{type:'noun',role:'adverb'},relations:{},ruleId:'R_ZARF_NASB',ar:'',en:'',
      phraseAr:'',phraseEn:'',phraseLabel:'',enHint:'',target:false,expectedSurface:'الْيَوْمَ',
      state:'nasb',sign:null,why:null,phraseWhy:null});
  });
  mustReject('repeated لا',base,data=>{
    data.tokens.splice(2,0,{word:'لَا',surfaceHint:'لَا',gloss:'no',id:data.templateId+':T0',
      grammar:{type:'particle',role:'particle',particleType:api.LA_JINS_PARTICLE_TYPE},relations:{},
      ruleId:api.LA_JINS_PARTICLE.ruleId,ar:'',en:'',phraseAr:'',phraseEn:'',phraseLabel:'',
      enHint:'',target:false,expectedSurface:'لَا',sign:null,why:null,phraseWhy:null});
  });
  // State forgeries, and the collision with the other nominal-governing frame the app produces.
  mustReject('اسم لا forced out of naṣb',base,data=>{data.tokens[1].state='raf'},'E_ROLE_CASE');
  mustReject('خبر لا forced out of rafʿ',base,data=>{data.tokens[3].state='nasb'},'E_ROLE_CASE');
  mustReject('اسم إنّ relabelled اسم لا',api.buildTemplate(api.templates.find(t=>
    api.buildTemplate(t.id).tokens.some(x=>x.grammar.role==='ismInna')).id),data=>{
    const t=data.tokens.find(item=>item.grammar.role==='ismInna');
    t.grammar.role=api.ISM_LA_ROLE;t.ruleId='R_ISM_LA_NASB';
  });
  mustReject('اسم لا relabelled اسم إنّ',base,data=>{
    const t=data.tokens[1];t.grammar.role='ismInna';t.ruleId='R_INNA_GOVERNS_NOMINAL';
  },'E_INNA_PAIR');
  mustReject('unregistered noun inventing an اسم لا',base,data=>{
    const other=api.LA_JINS_LEXEMES.possessor,t=data.tokens[1];
    t.word=other.acc;t.surfaceHint=other.acc;t.expectedSurface=other.acc;
  });
  mustReject('forged pair on the relationship',base,data=>{
    data.relationships.find(item=>item.type==='laJins').pairKey='personOfGood';
  },'E_LA_JINS_RELATION');
  /* History forgery: relabelling the frame's noun must not survive restoration. */
  {
    const forged=api.createExerciseSnapshot(base);
    forged.tokens[1].grammar.role='ismInna';
    const rebuilt=api.restoreExerciseSnapshot(forged);
    assert(!rebuilt||rebuilt.tokens[1].grammar.role===api.ISM_LA_ROLE,
      'History restored a «لا» al-jins noun under a different governing frame');
    negatives++;
  }
  console.log('La Nafiya lil-Jins focused tests: '+builds+' canonical builds, '+trips+' History round trips, '
    +negatives+' negative/collision boundaries — green');
}
runLaJinsFocusedTests();
if(process.env.NAHW_FOCUSED_LA_JINS==='1')process.exit(0);
/* ---- الاستثناء: Al-Tuḥfah pp. 162–165. ONE of the source's three أحوال is productive — the
   only one it makes obligatory — so most of what follows proves that the other two cannot be
   reached, and that a مستثنى is never just a manṣūb noun standing after a group. ---- */
function runMustathnaFocusedTests(){
  const clone=value=>JSON.parse(JSON.stringify(value));
  const analyzed=(template,built)=>api.completeNominalAnalysis({...built,templateId:template.stableId,
    templateStarts:template.starts,templateForm:template.form,templateState:template.state,templateSign:template.sign});
  const templateFor=pairKey=>api.templates.find(item=>item.mustathnaPairKeys.includes(pairKey));
  const built=new Map();
  let builds=0,trips=0,negatives=0;
  assert(Object.isFrozen(api.MUSTATHNA_PAIR_REGISTRY)&&Object.isFrozen(api.MUSTATHNA_LEXEMES)
    &&Object.isFrozen(api.ISTITHNA_TOOLS),'an istithnāʾ registry is mutable');
  /* Byte gate. Every مستثنى surface resolves to its OWN canonical record — «طَالِبٌ» is the naʿt
     chapter's record, reused rather than retyped, which is exactly what stops a second
     combining-mark variant of one word entering the noun index. */
  for(const [key,entry] of Object.entries(api.MUSTATHNA_LEXEMES)){
    assert(Object.isFrozen(entry)&&entry.lexeme,key+' is not immutable istithnāʾ lexical authority');
    for(const form of ['acc','gen']){
      const registered=api.nounFormIndex.get(entry.lexeme[form]);
      assert(registered&&registered.lexeme===entry.lexeme,
        key+' does not round-trip byte-for-byte through the canonical noun index ('+form+')');
      assert(!entry.lexeme[form].startsWith('ال'),key+' is definite, so it names a group rather than an individual');
    }
    assert(api.mustathnaWhole(entry.wholeEn),key+' names no مستثنى منه');
    negatives++;
  }
  assert(api.MUSTATHNA_LEXEMES.student.lexeme===api.NAAT_LEXEMES.studentIndef,
    'the istithnāʾ registry duplicated a word the naʿt registry already owns');
  assert(api.nounFormIndex.get(api.ISTITHNA_TOOLS.ghayr.acc)?.lexeme===api.ISTITHNA_TOOLS.ghayr,
    '«غَيْرَ» did not round-trip through the noun index');
  negatives+=2;
  for(const [pairKey,pair] of Object.entries(api.MUSTATHNA_PAIR_REGISTRY)){
    assert(Object.isFrozen(pair),pairKey+' is not immutable istithnāʾ pair authority');
    const template=templateFor(pairKey);
    assert(template,pairKey+' is unreachable: no template names it');
    const data=analyzed(template,api.buildMustathnaExercise(pairKey));
    const index=data.tokens.findIndex(item=>item.grammar.role===api.MUSTATHNA_ROLE);
    const mustathna=data.tokens[index],authority=api.deriveMustathnaAuthority(data,index);
    const relation=data.relationships.find(item=>item.type==='istithna');
    const tool=api.ISTITHNA_TOOLS[pair.toolKey];
    const isParticle=tool.kind===api.ISTITHNA_TOOL_KINDS.particle;
    const whole=api.mustathnaWhole(pair.wholeEn);
    assert(authority.authorized&&authority.pairKey===pairKey&&authority.toolKey===pair.toolKey,
      pairKey+' did not earn exact istithnāʾ authority');
    assert(mustathna.target&&mustathna.state==='nasb'&&mustathna.ruleId==='R_MUSTATHNA_NASB',
      pairKey+' did not produce its mustathnā as the manṣūb focus');
    assert(api.safeSignId(mustathna.sign)===api.GRAMMAR_RULES.nounInflection.singular.nasb[0],
      pairKey+' bypassed the canonical noun naṣb matrix');
    /* تام: the group excepted from is present and marfūʿ. That is what makes the speech complete,
       and it is the condition the whole obligatory ruling rests on. */
    assert(data.tokens[1].grammar.role==='faail'&&data.tokens[1].word===whole.nom
      &&data.tokens[1].state==='raf'&&authority.wholeId===data.tokens[1].id,
      pairKey+' lost the mentioned mustathnā minhu its تام condition requires');
    // مُوجَب: no negating, prohibiting or interrogative particle stands anywhere in the clause.
    assert(data.tokens.every(item=>item.grammar.type!=='particle'
      ||!api.ISTITHNA_NEGATION_PARTICLE_TYPES?.includes?.(item.grammar.particleType)),
      pairKey+' produced a negated clause under the obligatory-naṣb ḥāl');
    if(isParticle){
      assert(data.tokens[2].grammar.type==='particle'&&data.tokens[2].grammar.particleType===api.ISTITHNA_ILLA_TYPE
        &&data.tokens[2].word===tool.surface&&data.tokens[2].ruleId===tool.ruleId
        &&!mustathna.grammar.isMudaf,pairKey+' lost its إِلَّا particle');
    }else{
      /* غَيْرَ is itself the مستثنى, and the noun it excepts is khafḍ by iḍāfah — p. 164. The
         learner-facing khafḍ wording is checked here, not just the state. */
      assert(mustathna.word===tool.acc&&mustathna.grammar.isMudaf
        &&data.tokens[3].grammar.role==='mudafIlayh'&&data.tokens[3].state==='jarr'
        &&data.tokens[3].ar.includes('مَخْفُوضٌ')&&!data.tokens[3].ar.includes('مَجْرُورٌ'),
        pairKey+' lost the غَيْر iḍāfah frame or its khafḍ terminology');
    }
    assert(relation&&relation.ruleId==='RL_ISTITHNA_EXCLUSION'&&relation.mustathnaId===mustathna.id
      &&relation.wholeId===data.tokens[1].id&&relation.toolKey===pair.toolKey,
      pairKey+' lacks its canonical exclusion relationship');
    assert(api.isSourceAuthorized(mustathna.ruleId)&&api.isSourceAuthorized(relation.ruleId)
      &&api.isSourceAuthorized('R_ISTITHNA_CONDITIONS')&&api.isSourceAuthorized('R_ISTITHNA_ILLA'),
      pairKey+' lost source ownership');
    assert(mustathna.ar.includes('مُسْتَثْنًى مَنْصُوبٌ')&&!mustathna.ar.includes('بَدَلٌ')
      &&mustathna.why.ids.includes('WHY_ROLE_MUSTATHNA')&&mustathna.why.ids.includes('WHY_STATE_MUSTATHNA')
      &&mustathna.why.ids.includes('WHY_MUSTATHNA_TAAM_MUJAB')
      &&mustathna.phraseWhy?.ids.includes('WHY_REL_ISTITHNA_EXCLUSION'),
      pairKey+' Why/iʿrāb chain is incomplete');
    assert(mustathna.phraseLabel==='Istithnāʾ construction'&&data.tokens.every(item=>item===mustathna||!item.phraseAr),
      pairKey+' put the combined analysis somewhere other than the mustathnā');
    assert(api.canonicalMustathnaTranslation(data)===pair.sentenceEn
      &&api.composeCanonicalTranslation(data)===pair.sentenceEn&&data.translation===pair.sentenceEn,
      pairKey+' translation is not canonical natural English');
    const snapshot=api.createExerciseSnapshot(data),restored=snapshot&&api.restoreExerciseSnapshot(snapshot);
    assert(restored&&api.validateExercise(clone(restored)).length===0
      &&api.deriveMustathnaAuthority(restored,index).authorized,pairKey+' failed its History v3 round trip');
    assert(restored.sentence===data.sentence&&restored.translation===data.translation
      &&restored.tokens[index].ar===mustathna.ar&&restored.tokens[index].gloss===mustathna.gloss,
      pairKey+' changed learner presentation after History');
    built.set(pairKey,data);builds++;trips++;
  }
  assert(new Set([...built.values()].map(d=>d.relationships.find(r=>r.type==='istithna').toolKey)).size===2,
    'both registered أدوات are not productive');
  const illaBase=built.get('studentsIlla'),ghayrBase=built.get('studentsGhayr');
  const mustReject=(label,source,mutate,expected='E_MUSTATHNA_AUTHORITY')=>{
    const data=clone(source);mutate(data);const failures=api.validateExercise(data);
    assert(failures.some(item=>item.code===expected),label+' was accepted: '+failures.map(item=>item.code).join(','));negatives++;
  };
  /* مستثنى vs بدل — the collision this chapter turns on. p. 164 permits البدل only in NEGATED
     complete speech, which this lane never produces, so a badal label here must fail. */
  mustReject('mustathnā relabelled badal',illaBase,data=>{
    const m=data.tokens[3];m.grammar.role='badal';m.ruleId='R_BADAL_FOLLOWER';
  },'E_BADAL_AUTHORITY');
  const badalTemplate=api.templates.find(item=>item.followerKind===api.BADAL_KIND);
  const badalBase=api.buildTemplate(badalTemplate.id);
  mustReject('badal relabelled mustathnā',badalBase,data=>{
    const b=data.tokens.find(item=>item.grammar.role==='badal');
    b.grammar.role=api.MUSTATHNA_ROLE;b.ruleId='R_MUSTATHNA_NASB';
  });
  // مستثنى vs the other manṣūbāt.
  mustReject('object relabelled mustathnā',api.buildTemplate(api.templates.find(t=>t.tamyizPairKeys.length).id),data=>{
    const o=data.tokens.find(item=>item.grammar.role==='object');
    o.grammar.role=api.MUSTATHNA_ROLE;o.ruleId='R_MUSTATHNA_NASB';
  });
  mustReject('haal relabelled mustathnā',api.buildTemplate(api.templates.find(t=>t.haalPairKeys.length).id),data=>{
    const h=data.tokens.find(item=>item.grammar.role===api.HAAL_ROLE);
    h.grammar.role=api.MUSTATHNA_ROLE;h.ruleId='R_MUSTATHNA_NASB';
  });
  mustReject('tamyīz relabelled mustathnā',api.buildTemplate(api.templates.find(t=>t.tamyizPairKeys.length).id),data=>{
    const t=data.tokens.find(item=>item.grammar.role===api.TAMYIZ_ROLE);
    t.grammar.role=api.MUSTATHNA_ROLE;t.ruleId='R_MUSTATHNA_NASB';
  });
  /* الحالة الثانية must stay unreachable: negate the clause and the source stops making naṣb
     obligatory, so the authority has to withhold rather than keep the same analysis. */
  mustReject('negated clause claiming the obligatory ḥāl',illaBase,data=>{
    data.tokens.splice(0,0,{word:'مَا',surfaceHint:'مَا',gloss:'not',id:data.templateId+':T0',
      grammar:{type:'particle',role:'particle',particleType:'maNafiyaKana'},relations:{},
      ruleId:'R_MA_NAFIYA_KANA',ar:'',en:'',phraseAr:'',phraseEn:'',phraseLabel:'',
      enHint:'',target:false,expectedSurface:'مَا',sign:null,why:null,phraseWhy:null});
  });
  // الاتصال and the registry: nothing may be excepted from a group it does not belong to.
  mustReject('excepting an outsider from the group',illaBase,data=>{
    const other=api.MUSTATHNA_LEXEMES.guest.lexeme,m=data.tokens[3];
    m.word=other.acc;m.surfaceHint=other.acc;m.expectedSurface=other.acc;
  });
  mustReject('unregistered noun inventing a mustathnā',illaBase,data=>{
    const other=api.nounLexicons.singularPeople.find(item=>item.en==='the teacher'),m=data.tokens[3];
    m.word=other.acc;m.surfaceHint=other.acc;m.expectedSurface=other.acc;
  });
  mustReject('mustathnā forced out of naṣb',illaBase,data=>{data.tokens[3].state='raf'},'E_ROLE_CASE');
  mustReject('mustathnā minhu forced out of rafʿ',illaBase,data=>{data.tokens[1].state='nasb'},'E_ROLE_CASE');
  mustReject('إِلَّا replaced by another particle',illaBase,data=>{
    data.tokens[2].grammar.particleType='laNafiyaContext';data.tokens[2].word='لَا';data.tokens[2].surfaceHint='لَا';
  });
  mustReject('forged أداة on the relationship',illaBase,data=>{
    data.relationships.find(item=>item.type==='istithna').toolKey='ghayr';
  },'E_MUSTATHNA_RELATION');
  mustReject('wrong mustathnā minhu on the relationship',illaBase,data=>{
    data.relationships.find(item=>item.type==='istithna').wholeId=data.tokens[0].id;
  },'E_MUSTATHNA_RELATION');
  mustReject('غَيْر stripped of its iḍāfah',ghayrBase,data=>{data.tokens[2].grammar.isMudaf=false});
  /* History forgery: a snapshot whose أداة is relabelled must be rebuilt canonically, not
     restored into a construction the registry never authorized. */
  {
    const forged=api.createExerciseSnapshot(illaBase);
    const forgedRelation=forged.relationships.find(item=>item.type==='istithna');
    assert(forgedRelation,'the snapshot carries no istithnāʾ relationship to forge');
    forgedRelation.toolKey='ghayr';forgedRelation.toolKind=api.ISTITHNA_TOOL_KINDS.noun;
    const rebuilt=api.restoreExerciseSnapshot(forged);
    const rebuiltRelation=rebuilt&&rebuilt.relationships.find(item=>item.type==='istithna');
    assert(rebuiltRelation&&rebuiltRelation.toolKey==='illa'
      &&rebuiltRelation.toolKind===api.ISTITHNA_TOOL_KINDS.particle,
      'History did not discard and canonically rebuild a forged istithnāʾ relationship');
    negatives++;
  }
  console.log('Mustathna focused tests: '+builds+' canonical builds, '+trips+' History round trips, '
    +negatives+' negative/collision boundaries — green');
}
runMustathnaFocusedTests();
if(process.env.NAHW_FOCUSED_MUSTATHNA==='1')process.exit(0);
/* ---- التمييز: Al-Tuḥfah pp. 157–162. Both source divisions, and the boundaries that keep them
   apart from each other and from every other manṣūb role. The two lanes share one token shape on
   purpose, so most of what follows is about proving that the SHAPE never decides anything. ---- */
function runTamyizFocusedTests(){
  const clone=value=>JSON.parse(JSON.stringify(value));
  const analyzed=(template,built)=>api.completeNominalAnalysis({...built,templateId:template.stableId,
    templateStarts:template.starts,templateForm:template.form,templateState:template.state,templateSign:template.sign});
  const templateFor=pairKey=>api.templates.find(item=>item.tamyizPairKeys.includes(pairKey));
  const built=new Map();
  let builds=0,trips=0,negatives=0;
  assert(Object.isFrozen(api.TAMYIZ_PAIR_REGISTRY)&&Object.isFrozen(api.TAMYIZ_LEXEMES)
    &&Object.isFrozen(api.TAMYIZ_MEASURE_LEXEMES),'a tamyīz registry is mutable');
  /* Byte gate. Every registered surface must resolve to its own record in the live noun index; a
     combining-mark typo would fail here rather than reaching surfaceHint at build time. */
  for(const [key,lexeme] of Object.entries({...api.TAMYIZ_LEXEMES,...api.TAMYIZ_MEASURE_LEXEMES})){
    assert(Object.isFrozen(lexeme),key+' is not immutable tamyīz lexical authority');
    const registered=api.nounFormIndex.get(lexeme.acc);
    assert(registered&&registered.lexeme===lexeme,
      key+' does not round-trip byte-for-byte through the canonical noun index');
    assert(!lexeme.acc.startsWith('ال')&&/(?:ً|ًا)$/u.test(lexeme.acc),
      key+' is not an indefinite accusative, which p. 159 requires');
    assert(!lexeme.nom&&!lexeme.gen,key+' registers case forms no productive lane uses');
    negatives++;
  }
  for(const [pairKey,pair] of Object.entries(api.TAMYIZ_PAIR_REGISTRY)){
    assert(Object.isFrozen(pair),pairKey+' is not immutable tamyīz pair authority');
    const template=templateFor(pairKey);
    assert(template,pairKey+' is unreachable: no template names it');
    const data=analyzed(template,api.buildTamyizExercise(pairKey));
    const index=data.tokens.findIndex(item=>item.grammar.role===api.TAMYIZ_ROLE);
    const tamyiz=data.tokens[index],authority=api.deriveTamyizAuthority(data,index);
    const verb=data.tokens.find(item=>item.id===authority.verbId);
    const relation=data.relationships.find(item=>item.type==='tamyiz');
    const lexeme=api.TAMYIZ_LEXEMES[pair.tamyizKey];
    const isDhat=pair.subtype===api.TAMYIZ_SUBTYPES.dhat;
    assert(authority.authorized&&authority.pairKey===pairKey&&authority.subtype===pair.subtype,
      pairKey+' did not earn exact tamyīz authority');
    assert(tamyiz.target&&tamyiz.state==='nasb'&&tamyiz.ruleId==='R_TAMYIZ_NASB'&&tamyiz.word===lexeme.acc,
      pairKey+' did not produce its tamyīz as the manṣūb focus');
    assert(api.safeSignId(tamyiz.sign)===api.GRAMMAR_RULES.nounInflection.singular.nasb[0],
      pairKey+' bypassed the canonical noun naṣb matrix');
    assert(index===data.tokens.length-1&&data.tokens[1].grammar.role==='faail'&&data.tokens[1].state==='raf',
      pairKey+' does not place the tamyīz after a clause that is already complete');
    // The division decides what is clarified, and each division carries the other's opposite.
    assert(authority.mubayyanKind===(isDhat?'noun':'nisbah'),pairKey+' resolved the wrong kind of ambiguity');
    if(isDhat){
      const measure=api.TAMYIZ_MEASURE_LEXEMES[pair.measureKey];
      assert(authority.mubayyanId===data.tokens[2].id&&authority.mubayyanWord===measure.acc
        &&api.TAMYIZ_MEASURE_KINDS[authority.measureKind],pairKey+' lost its مقدار');
    }else{
      assert(!authority.mubayyanId&&!authority.measureKind&&data.tokens[2].word.startsWith('ال'),
        pairKey+' invented a token-level mubayyan for a tamyīz al-nisbah');
    }
    assert(relation&&relation.ruleId==='RL_TAMYIZ_MUBAYYAN'&&relation.verbId===verb.id
      &&relation.tamyizId===tamyiz.id&&relation.subtype===pair.subtype
      &&relation.mubayyanId===(isDhat?data.tokens[2].id:''),
      pairKey+' lacks its canonical ʿāmil/mubayyan relationship');
    assert(api.isSourceAuthorized(tamyiz.ruleId)&&api.isSourceAuthorized(relation.ruleId)
      &&api.isSourceAuthorized(isDhat?'R_TAMYIZ_DHAT':'R_TAMYIZ_NISBAH')
      &&api.isSourceAuthorized('R_TAMYIZ_CONDITIONS'),pairKey+' lost source ownership');
    assert(tamyiz.ar.includes('تَمْيِيزٌ مَنْصُوبٌ')&&!tamyiz.ar.includes('حَالٌ')
      &&tamyiz.why.ids.includes('WHY_ROLE_TAMYIZ_'+pair.subtype.toUpperCase())
      &&tamyiz.why.ids.includes('WHY_STATE_TAMYIZ')
      &&tamyiz.why.ids.includes(isDhat?'WHY_TAMYIZ_DHAT':'WHY_TAMYIZ_NISBAH')
      &&tamyiz.why.ids.includes('WHY_TAMYIZ_CONDITIONS')
      &&tamyiz.phraseWhy?.ids.includes(isDhat?'WHY_REL_TAMYIZ_DHAT':'WHY_REL_TAMYIZ_NISBAH'),
      pairKey+' Why/iʿrāb chain is incomplete');
    assert(tamyiz.phraseLabel==='Tamyīz construction'&&data.tokens.every(item=>item===tamyiz||!item.phraseAr),
      pairKey+' put the combined analysis somewhere other than the tamyīz');
    assert(api.canonicalTamyizTranslation(data)===pair.sentenceEn
      &&api.composeCanonicalTranslation(data)===pair.sentenceEn&&data.translation===pair.sentenceEn
      &&!/ as a /.test(data.translation),pairKey+' translation is not canonical natural English');
    const snapshot=api.createExerciseSnapshot(data),restored=snapshot&&api.restoreExerciseSnapshot(snapshot);
    assert(restored&&api.validateExercise(clone(restored)).length===0
      &&api.deriveTamyizAuthority(restored,index).authorized,pairKey+' failed its History v3 round trip');
    assert(restored.sentence===data.sentence&&restored.translation===data.translation
      &&restored.tokens[index].ar===tamyiz.ar&&restored.tokens[index].gloss===tamyiz.gloss,
      pairKey+' changed learner presentation after History');
    built.set(pairKey,data);builds++;trips++;
  }
  // Both source divisions are actually reached, and the declared morphology scope is truthful.
  assert(new Set([...built.values()].map(data=>data.relationships.find(r=>r.type==='tamyiz').subtype)).size===2,
    'the two source divisions are not both productive');
  assert(new Set([...built.values()].map(data=>data.tokens[data.tokens.length-1].inflection)).size===1
    &&[...built.values()].every(data=>api.safeSignId(data.tokens[data.tokens.length-1].sign)==='fatha'),
    'the declared singular/fatḥah-only tamyīz scope is not truthful');
  const dhatBase=built.get('cupOfWater'),nisbahBase=built.get('filledCup');
  const mustReject=(label,source,mutate,expected='E_TAMYIZ_AUTHORITY')=>{
    const data=clone(source);mutate(data);const failures=api.validateExercise(data);
    assert(failures.some(item=>item.code===expected),label+' was accepted: '+failures.map(item=>item.code).join(','));negatives++;
  };
  /* التمييز vs الحال — the collision this chapter turns on. Both are indefinite accusatives at the
     end of a clause, so the ONLY thing that can separate them is which registry owns the token. */
  mustReject('tamyīz relabelled haal',dhatBase,data=>{
    const t=data.tokens[3];t.grammar.role=api.HAAL_ROLE;t.ruleId='R_HAAL_NASB';
  },'E_HAAL_AUTHORITY');
  const haalTemplate=api.templates.find(item=>item.haalPairKeys.includes('studentSmiling'));
  const haalBase=analyzed(haalTemplate,api.buildHaalExercise('studentSmiling'));
  mustReject('haal relabelled tamyīz',haalBase,data=>{
    const h=data.tokens.find(item=>item.grammar.role===api.HAAL_ROLE);
    h.grammar.role=api.TAMYIZ_ROLE;h.ruleId='R_TAMYIZ_NASB';
  });
  /* التمييز vs the other manṣūbāt. A manṣūb noun does not become a tamyīz by being relabelled,
     and the tamyīz token does not become one of them either. */
  mustReject('direct object relabelled tamyīz',dhatBase,data=>{
    const o=data.tokens[2];o.grammar.role=api.TAMYIZ_ROLE;o.ruleId='R_TAMYIZ_NASB';
  });
  mustReject('tamyīz relabelled direct object',dhatBase,data=>{
    const t=data.tokens[3];t.grammar.role='object';t.ruleId='R_MAFUL_BIHI_NASB';
  },'E_ORPHAN_OBJECT');
  const mutlaqTemplate=api.templates.find(item=>item.mutlaqPairKeys&&item.mutlaqPairKeys.length);
  const mutlaqBase=api.buildTemplate(mutlaqTemplate.id);
  mustReject('mafʿūl muṭlaq relabelled tamyīz',mutlaqBase,data=>{
    const m=data.tokens.find(item=>item.grammar.role==='mafulMutlaq');
    m.grammar.role=api.TAMYIZ_ROLE;m.ruleId='R_TAMYIZ_NASB';
  });
  const zarfTemplate=api.templates.find(item=>item.mafulFihPairKeys&&item.mafulFihPairKeys.length);
  const zarfBase=api.buildTemplate(zarfTemplate.id);
  mustReject('ẓarf relabelled tamyīz',zarfBase,data=>{
    const z=data.tokens.find(item=>item.grammar.role===api.MAFUL_FIH_ROLE);
    z.grammar.role=api.TAMYIZ_ROLE;z.ruleId='R_TAMYIZ_NASB';
  });
  // An unregistered indefinite accusative cannot invent the role, even in a licensed template.
  mustReject('unregistered noun inventing tamyīz',dhatBase,data=>{
    const t=data.tokens[3],other=api.TAMYIZ_MEASURE_LEXEMES.pound;
    t.word=other.acc;t.surfaceHint=other.acc;t.expectedSurface=other.acc;
  });
  // p. 159's nakirah condition, and the state and division the authority pins.
  mustReject('definite tamyīz',dhatBase,data=>{
    const t=data.tokens[3],definite=api.tamyizNoun('singularThings','the water');
    t.word=definite.acc;t.surfaceHint=definite.acc;t.expectedSurface=definite.acc;
  });
  mustReject('tamyīz forced out of naṣb',dhatBase,data=>{data.tokens[3].state='raf'},'E_ROLE_CASE');
  mustReject('forged subtype on the relationship',dhatBase,data=>{
    data.relationships.find(item=>item.type==='tamyiz').subtype=api.TAMYIZ_SUBTYPES.nisbah;
  },'E_TAMYIZ_RELATION');
  mustReject('tamyīz al-nisbah given a mubayyan link',nisbahBase,data=>{
    const rel=data.relationships.find(item=>item.type==='tamyiz');
    rel.mubayyanId=data.tokens[2].id;data.tokens[3].relations.mubayyanId=data.tokens[2].id;
  },'E_TAMYIZ_RELATION');
  mustReject('wrong ʿāmil on the relationship',dhatBase,data=>{
    data.relationships.find(item=>item.type==='tamyiz').verbId=data.tokens[1].id;
  },'E_TAMYIZ_RELATION');
  // An unauthorized pairing: a registered tamyīz its template's pairs never license.
  mustReject('unauthorized ʿāmil/tamyīz pairing',dhatBase,data=>{
    const oil=api.TAMYIZ_LEXEMES.oil,t=data.tokens[3];
    t.word=oil.acc;t.surfaceHint=oil.acc;t.expectedSurface=oil.acc;
  });
  /* History forgery: a relabelled role must not survive restoration by being rebuilt into
     something plausible. The canonical rebuild has to restore the registered division. */
  {
    const forged=api.createExerciseSnapshot(dhatBase);
    const forgedRelation=forged.relationships.find(item=>item.type==='tamyiz');
    assert(forgedRelation,'the snapshot carries no tamyīz relationship to forge');
    forgedRelation.subtype=api.TAMYIZ_SUBTYPES.nisbah;forgedRelation.mubayyanId='';
    const rebuilt=api.restoreExerciseSnapshot(forged);
    const rebuiltRelation=rebuilt&&rebuilt.relationships.find(item=>item.type==='tamyiz');
    assert(rebuiltRelation&&rebuiltRelation.subtype===api.TAMYIZ_SUBTYPES.dhat
      &&rebuiltRelation.mubayyanId===rebuilt.tokens[2].id,
      'History did not discard and canonically rebuild a forged tamyīz relationship');
    negatives++;
  }
  console.log('Tamyiz focused tests: '+builds+' canonical builds, '+trips+' History round trips, '
    +negatives+' negative/registry boundaries — green');
}
runTamyizFocusedTests();
if(process.env.NAHW_FOCUSED_TAMYIZ==='1')process.exit(0);
/* ---- الحال المفردة: definite صاحب, indefinite accusative haal, explicit event/owner proof. ---- */
function runHaalFocusedTests(){
  const clone=value=>JSON.parse(JSON.stringify(value));
  const analyzed=(template,built)=>api.completeNominalAnalysis({...built,templateId:template.stableId,
    templateStarts:template.starts,templateForm:template.form,templateState:template.state,templateSign:template.sign});
  const templateFor=pairKey=>api.templates.find(item=>item.haalPairKeys.includes(pairKey));
  const built=new Map();
  let builds=0,trips=0,negatives=0;
  assert(Object.isFrozen(api.HAAL_PAIR_REGISTRY)&&Object.isFrozen(api.HAAL_LEXEMES),
    'a haal registry is mutable');
  for(const [key,entry] of Object.entries(api.HAAL_LEXEMES)){
    assert(Object.isFrozen(entry),key+' is not immutable haal lexical authority');
    const registered=api.nounFormIndex.get(entry.lexeme.acc);
    assert(registered&&registered.lexeme===entry.lexeme,
      key+' does not round-trip byte-for-byte through its canonical noun record');
  }
  for(const [pairKey,pair] of Object.entries(api.HAAL_PAIR_REGISTRY)){
    assert(Object.isFrozen(pair),pairKey+' is not immutable haal pair authority');
    const template=templateFor(pairKey);
    assert(template,pairKey+' is unreachable: no template names it');
    const data=analyzed(template,api.buildHaalExercise(pairKey));
    const index=data.tokens.findIndex(item=>item.grammar.role===api.HAAL_ROLE);
    const haal=data.tokens[index],authority=api.deriveHaalAuthority(data,index);
    const sahib=data.tokens.find(item=>item.id===authority.sahibId);
    const verb=data.tokens.find(item=>item.id===authority.verbId);
    const relation=data.relationships.find(item=>item.type==='haal');
    const entry=api.HAAL_LEXEMES[pair.haalKey];
    assert(authority.authorized&&authority.pairKey===pairKey&&authority.sahibRole===pair.ownerRole,
      pairKey+' did not earn exact haal authority');
    assert(haal.target&&haal.state==='nasb'&&haal.ruleId==='R_HAAL_NASB'&&haal.word===entry.lexeme.acc,
      pairKey+' did not produce its haal as the manṣūb focus');
    assert(api.safeSignId(haal.sign)===api.GRAMMAR_RULES.nounInflection.singular.nasb[0],
      pairKey+' bypassed the canonical noun naṣb matrix');
    assert(sahib&&sahib.grammar.role===pair.ownerRole&&sahib.word.startsWith('ال')
      &&!entry.lexeme.nom.startsWith('ال'),pairKey+' lost the definite-owner/indefinite-haal contract');
    assert(authority.gender===pair.gender&&authority.number===pair.number
      &&authority.gender==='masculine'&&authority.number==='singular',pairKey+' lost its narrow agreement contract');
    assert(relation&&relation.ruleId==='RL_HAAL_OWNER'&&relation.verbId===verb.id
      &&relation.sahibId===sahib.id&&relation.haalId===haal.id&&relation.pairKey===pairKey,
      pairKey+' lacks its canonical event/owner relationship');
    assert(api.isSourceAuthorized(haal.ruleId)&&api.isSourceAuthorized(relation.ruleId),
      pairKey+' lost source ownership');
    assert(haal.ar.includes('حَالٌ مَنْصُوبٌ')&&!haal.ar.includes('نَعْتٌ')
      &&haal.why.ids.includes('WHY_ROLE_HAAL')&&haal.why.ids.includes('WHY_STATE_HAAL')
      &&haal.why.ids.includes('WHY_HAAL_DEFINITENESS')
      &&haal.phraseWhy?.ids.includes('WHY_REL_HAAL_OWNER'),pairKey+' Why/iʿrāb chain is incomplete');
    assert(haal.phraseLabel==='Haal construction'&&data.tokens.every(item=>item===haal||!item.phraseAr),
      pairKey+' put the combined analysis somewhere other than the haal');
    assert(api.canonicalHaalTranslation(data)===pair.sentenceEn
      &&api.composeCanonicalTranslation(data)===pair.sentenceEn&&data.translation===pair.sentenceEn,
      pairKey+' translation is not canonical natural English');
    const snapshot=api.createExerciseSnapshot(data),restored=snapshot&&api.restoreExerciseSnapshot(snapshot);
    assert(restored&&api.validateExercise(clone(restored)).length===0
      &&api.deriveHaalAuthority(restored,index).authorized,pairKey+' failed its History v3 round trip');
    assert(restored.sentence===data.sentence&&restored.translation===data.translation
      &&restored.tokens[index].ar===haal.ar&&restored.tokens[index].gloss===haal.gloss,
      pairKey+' changed learner presentation after History');
    built.set(pairKey,data);builds++;trips++;
  }
  assert(new Set([...built.values()].map(data=>data.tokens.find(item=>item.grammar.role===api.HAAL_ROLE).inflection)).size===1,
    'the declared singular-only haal scope is not truthful');
  const subjectBase=built.get('studentSmiling'),objectBase=built.get('garmentNew');
  const mustReject=(label,source,mutate,expected='E_HAAL_AUTHORITY')=>{
    const data=clone(source);mutate(data);const failures=api.validateExercise(data);
    assert(failures.some(item=>item.code===expected),label+' was accepted: '+failures.map(item=>item.code).join(','));negatives++;
  };
  // الحال owns naṣb; it never enters the four-axis naʿt inheritance path.
  mustReject('haal relabelled naat',subjectBase,data=>{const h=data.tokens[2];h.grammar.role='naat';h.ruleId='R_NAAT_HAQIQI'},'E_NAAT_AUTHORITY');
  const naatTemplate=api.templates.find(item=>item.stableId==='T_PARTICLE_SINGULAR_NASB_FATHA_08');
  const naatBase=analyzed(naatTemplate,api.buildNaatExercise('singularDefM','nasb'));
  mustReject('naat relabelled haal',naatBase,data=>{const n=data.tokens.find(item=>item.grammar.role==='naat');n.grammar.role=api.HAAL_ROLE;n.ruleId='R_HAAL_NASB'},'E_HAAL_AUTHORITY');
  mustReject('arbitrary adjective inventing haal',subjectBase,data=>{
    const h=data.tokens[2],other=api.nounLexicons.singularPredicates.find(item=>item.en==='sick');
    h.word=other.acc;h.surfaceHint=other.acc;h.expectedSurface=other.acc;
  });
  mustReject('wrong صاحب relation',subjectBase,data=>{
    data.relationships.find(item=>item.type==='haal').sahibId=data.tokens[0].id;
  },'E_HAAL_RELATION');
  mustReject('wrong haal state',subjectBase,data=>{data.tokens[2].state='raf'},'E_ROLE_CASE');
  mustReject('indefinite صاحب',subjectBase,data=>{
    const n=api.NAAT_PAIR_REGISTRY.singularIndefM.followed;
    data.tokens[1].word=n.nom;data.tokens[1].surfaceHint=n.nom;data.tokens[1].expectedSurface=n.nom;
  });
  mustReject('definite haal',subjectBase,data=>{
    const n=api.NAAT_PAIR_REGISTRY.singularDefM.follower;
    data.tokens[2].word=n.acc;data.tokens[2].surfaceHint=n.acc;data.tokens[2].expectedSurface=n.acc;
  });
  mustReject('gender mismatch',subjectBase,data=>{
    const n=api.NAAT_PAIR_REGISTRY.singularIndefF.follower;
    data.tokens[2].word=n.acc;data.tokens[2].surfaceHint=n.acc;data.tokens[2].expectedSurface=n.acc;
  });
  mustReject('number mismatch',subjectBase,data=>{
    const n=api.NAAT_PAIR_REGISTRY.dualDefM.follower;
    data.tokens[2].word=n.acc;data.tokens[2].surfaceHint=n.acc;data.tokens[2].expectedSurface=n.acc;
  });
  mustReject('unauthorized event/haal pair',subjectBase,data=>{
    data.tokens[0].word='وَقَفَ';data.tokens[0].surfaceHint='وَقَفَ';data.tokens[0].expectedSurface='وَقَفَ';
  });
  mustReject('haal moved into unrelated order',subjectBase,data=>{data.tokens=[data.tokens[2],data.tokens[0],data.tokens[1]]});
  mustReject('wrong haal source rule',subjectBase,data=>{data.tokens[2].ruleId='R_NAAT_HAQIQI'},'E_HAAL_RULE');
  mustReject('object-owner pair assigned to subject',objectBase,data=>{
    const rel=data.relationships.find(item=>item.type==='haal');rel.sahibId=data.tokens[1].id;rel.sahibRole='faail';
  },'E_HAAL_RELATION');
  const forgedRole=api.createExerciseSnapshot(subjectBase);
  forgedRole.tokens[2].grammar.role='naat';forgedRole.tokens[2].ruleId='R_NAAT_HAQIQI';
  assert(api.restoreExerciseSnapshot(forgedRole)===null,'History accepted a haal-to-naat identity forgery');negatives++;
  const forgedRelation=api.createExerciseSnapshot(objectBase);
  const storedRelation=forgedRelation.relationships.find(item=>item.type==='haal');
  storedRelation.sahibId=forgedRelation.tokens[1].id;storedRelation.sahibRole='faail';storedRelation.pairKey='studentSmiling';
  const rebuilt=api.restoreExerciseSnapshot(forgedRelation),rebuiltRelation=rebuilt&&rebuilt.relationships.find(item=>item.type==='haal');
  assert(rebuiltRelation&&rebuiltRelation.sahibRole==='object'&&rebuiltRelation.pairKey==='garmentNew'
    &&rebuiltRelation.sahibId===rebuilt.tokens[2].id,
    'History did not discard and canonically rebuild a forged haal relationship');negatives++;
  console.log('Haal focused tests: '+builds+' canonical builds, '+trips+' History round trips, '
    +negatives+' negative/collision boundaries — green');
}
