assertFailureCode('tāʾ al-fāʿil replaced by feminine tāʾ',taaAsFeminine,'E_COMPONENT_SET');pastAdversarialCases++;
const feminineAsFail=clone(femPast);feminineAsFail.tokens[0].components[0].kind='taa-fail-1s';
